-- Reset generated Stage 1 data while keeping the registered public source catalog.
--
-- This intentionally preserves source_registry rows because they are the
-- configured public-source catalog, not compound evidence generated by a run.

TRUNCATE TABLE
    curation_event,
    export_job,
    user_activity_log,
    document_chunk,
    model_parameter_evidence,
    public_pbpk_model_validation_metric,
    public_pbpk_model_validation_dataset,
    public_pbpk_model_validation_run,
    public_pbpk_model_simulation,
    public_pbpk_model_asset,
    public_pbpk_model_version,
    public_pbpk_model_registry,
    enzyme_transporter_relationship,
    tissue_expression_evidence,
    protein_target_identity,
    ddi_evidence,
    special_population_evidence,
    clinical_pk_evidence,
    adme_parameter_evidence,
    physicochemical_property_evidence,
    compound_identity,
    parsed_document,
    raw_document,
    ingestion_run
RESTART IDENTITY CASCADE;

UPDATE source_registry
SET source_version = NULL,
    checksum = NULL,
    updated_at = now();
